#!/usr/bin/env python3
# Auto-generated by postprocessor::generate_LTS_convergence_script

import os
import math
import numpy as np
import matplotlib
import matplotlib.pyplot as plt
matplotlib.rcParams['text.usetex'] = True
from matplotlib.lines import Line2D

current_file_path = os.path.abspath(__file__)
current_directory = os.path.dirname(current_file_path)
os.chdir(current_directory)

k_max    = 3
l_max    = 3
n_divs   = 100
substeps = 1
discret  = 0

styles = {
    1: {'color': 'darkgreen', 'marker': '^'},
    2: {'color': 'orange',    'marker': 's'},
    3: {'color': 'darkred',   'marker': 'o'},
    4: {'color': 'navy',      'marker': 'd'},
    5: {'color': 'purple',    'marker': 'v'},
}

def parse_log(filename):
    if not os.path.isfile(filename):
        print(f'Fichier introuvable : {filename}')
        return None
    data = {}
    with open(filename) as f:
        lines = f.readlines()
    section = None
    for s in (l.strip() for l in lines):
        if 'Space step =' in s:
            data['h'] = float(s.split('=')[1])
        elif s == 'Elastic region :':
            section = 'elastic'
        elif s == 'Acoustic region :':
            section = 'acoustic'
        elif 'L2 errors of dG' in s:
            section = 'dg'
        elif s.startswith('L2-norm error') and section in ('elastic', 'acoustic'):
            val = float(s.split('=')[1])
            data['e_L2' if section == 'elastic' else 'a_L2'] = val
        elif s.startswith('Acoustic region :') and section == 'dg':
            data['a_dG'] = float(s.split(':')[1])
        elif s.startswith('Elastic  region') and section == 'dg':
            data['e_dG'] = float(s.split(':')[1])
    return data if 'h' in data and 'e_L2' in data else None

results = {k: {'h':[], 'e_L2':[], 'a_L2':[], 'e_dG':[], 'a_dG':[]}
           for k in range(1, k_max+1)}

for k in range(1, k_max+1):
    for l in range(0, l_max+1):
        fname = f'lts_l_{l}_n_{n_divs}_k_{k}_s_4_p_{substeps}_discret_{discret}.txt'
        d = parse_log(fname)
        if d is None: continue
        for key in ('h', 'e_L2', 'a_L2', 'e_dG', 'a_dG'):
            results[k][key].append(d.get(key, float('nan')))

def sorted_by_h(res_k, key):
    pairs = sorted(zip(res_k['h'], res_k[key]))
    return np.array([p[0] for p in pairs]), np.array([p[1] for p in pairs])

plt.figure(figsize=(8, 8))

for k in range(1, k_max+1):
    if not results[k]['h']: continue
    col = styles[k]['color']
    mrk = styles[k]['marker']

    h,  e_L2 = sorted_by_h(results[k], 'e_L2')
    _,  a_L2 = sorted_by_h(results[k], 'a_L2')
    _,  e_dG = sorted_by_h(results[k], 'e_dG')
    _,  a_dG = sorted_by_h(results[k], 'a_dG')
    L2_hho = e_L2 + a_L2
    L2_dg  = e_dG + a_dG

    # HHO -- trait plein
    plt.loglog(h, L2_hho, marker=mrk, linestyle='-',  color=col)
    # dG  -- pointille
    plt.loglog(h, L2_dg,  marker=mrk, linestyle='--', color=col, alpha=0.7)

handles = [
    Line2D([], [], color='k', linestyle='-',
           label=r'$\mathbf{||\cdot||_{\mathrm{HHO}}}$'),
    Line2D([], [], color='k', linestyle='--',
           label=r'$\mathbf{||\cdot||_{\mathrm{dG}}}$'),
]
for k in range(1, k_max+1):
    if not results[k]['h']: continue
    h,  e_L2 = sorted_by_h(results[k], 'e_L2')
    _,  a_L2 = sorted_by_h(results[k], 'a_L2')
    L2  = e_L2 + a_L2
    rate  = np.polyfit(np.log(h), np.log(L2), 1)[0]
    order = int(round(rate))
    lbl   = rf'$\mathbf{{k={k}}} \approx \mathcal{{O}}(h^{{{order}}})$'
    handles.append(Line2D([], [], color=styles[k]['color'],
                          marker=styles[k]['marker'],
                          linestyle='-', label=lbl))
plt.legend(handles=handles, labelcolor='linecolor',
           loc='lower right', framealpha=1, fontsize='12.5')

plt.yscale('log')
plt.xscale('log')
plt.minorticks_off()
plt.xlabel(r'$h$', fontsize=25, labelpad=20)
plt.ylabel(r'$\textsc{L}^2\textsc{-error}$', fontsize=25, labelpad=20)
plt.tick_params(axis='x', which='major', pad=10)
plt.tick_params(axis='y', which='major', pad=10)
plt.xticks(fontsize=20)
plt.yticks(fontsize=20)

ax = plt.gca()
ax.figure.canvas.draw()
xlim = ax.get_xlim()
ylim = ax.get_ylim()
lx0 = math.log10(xlim[0]); lx1 = math.log10(xlim[1])
ly0 = math.log10(ylim[0]); ly1 = math.log10(ylim[1])
triangle_x2 = 10**(lx0 + 0.55*(lx1-lx0))
triangle_x  = 10**(lx0 + 0.90*(lx1-lx0))
triangle_y  = 10**(ly0 + 0.04*(ly1-ly0))
p   = k_max
col = styles[p]['color']
y_top = math.exp(p * math.log(triangle_x / triangle_x2) + math.log(triangle_y))
tri   = np.array([[triangle_x,  triangle_y],
                   [triangle_x,  y_top],
                   [triangle_x2, triangle_y]])
plt.plot(tri[:,0], tri[:,1], color=col, linewidth=2.5)
plt.plot([triangle_x2, triangle_x, triangle_x],
         [triangle_y,  triangle_y, tri[1,1]],
         color='black', linewidth=2.5)
plt.text(triangle_x*1.04, y_top,
         f'$\\mathbf{{{p}}}$', fontsize=15, color=col)

plt.tight_layout()
plt.savefig('conv_LTS.png', dpi=300, bbox_inches='tight')
plt.savefig('conv_LTS.pdf', bbox_inches='tight')
print('Saved conv_LTS.png / conv_LTS.pdf')
plt.show()

print('\n=== Convergence rate summary (L2 HHO) ===')
print(f'{"k":>4} {"rate":>8}')
print('-'*14)
for k in range(1, k_max+1):
    if not results[k]['h']: continue
    h,  e_L2 = sorted_by_h(results[k], 'e_L2')
    _,  a_L2 = sorted_by_h(results[k], 'a_L2')
    L2 = e_L2 + a_L2
    rate = np.polyfit(np.log(h), np.log(L2), 1)[0]
    print(f'{k:>4} {rate:>8.3f}')

print()
for k in range(1, k_max+1):
    if not results[k]['h']: continue
    h,  e_L2 = sorted_by_h(results[k], 'e_L2')
    _,  a_L2 = sorted_by_h(results[k], 'a_L2')
    L2    = e_L2 + a_L2
    rates = np.log(L2[1:]/L2[:-1]) / np.log(h[1:]/h[:-1])
    for i, r in enumerate(rates):
        print(f'k={k}: h={h[i]:.4f} -> h={h[i+1]:.4f} : rate={r:.3f}')
